INSERT INTO `tb_blog` VALUES (1,5,101,'海底捞COCO Park 捞派毛肚七上八下绝了','','四宫格锅底点了番茄+牛油+清水+寿喜烧。必点捞派脆脆毛肚，七上八下涮完脆爽弹牙；大颗粒虾滑让服务员帮忙下番茄锅，Q弹鲜甜；现炸酥肉趁热吃，外皮酥脆蘸干碟。大学生六九折人均七十吃到撑。',43,8,'2026-10-19 14:43:10','2026-10-19 15:12:14'),(2,14,102,'纯K万象天地 曲库更新快到离谱','','纯K的音响确实是深圳KTV第一梯队，歌单每周更新，日韩新曲基本到店就能点。周末下午场人均八十，建议提前小程序预约。房费包含免费饮料自助。',38,6,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(3,3,103,'陶陶居 13道褶的大虾饺必点','','周末早茶来陶陶居，招牌大虾饺一只里三颗完整虾仁，薄皮13道褶，咬开汁水丰盈。酱皇蒸凤爪炖得软烂脱骨，酥皮水牛奶菠萝包流心内馅甜而不腻。环境雅致，适合带家人。',35,5,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(4,20,104,'超级猩猩 按次付费团课真香','','不用办年卡，按次约课。BP塑形课、BC搏击课氛围很好，教练会纠正动作。一次六十左右，比健身房划算。周末热门课提前三天约。',28,4,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(5,8,105,'温野菜 寿喜烧和牛吃到饱','','COCO Park的温野菜，寿喜锅底和昆布锅底双拼。和牛肩胛随便吃，蘸无菌蛋入口即化。冰淇淋、布丁随便拿，饮料自助。人均一百五吃到扶墙出。',31,5,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(6,27,106,'Helens小酒馆 学生党微醺圣地','','Helens价格真的亲民，科罗娜二十多一杯，鸡尾酒三十出头。东南亚风装修，晚上九点后氛围最好。适合学生党聚会微醺。',22,3,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(7,25,107,'meland 深圳室内乐园天花板','','meland真的是深圳室内乐园天花板，球池、螺旋滑梯、角色扮演区、模拟超市全都有。遛娃一整天都不重样，家长可以坐在休息区喝咖啡。',25,4,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(8,12,108,'奉天小馆 锅包肉外酥里嫩','','壹方城的奉天小馆，锅包肉酸甜口，外壳酥脆咬开有声。东北大饭包分量扎实，酱大骨炖得脱骨。东北菜分量大，两人点三个菜够吃。',26,3,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(9,22,109,'华夏良子 加班后足疗放松','','最近加班多，来壹方城华夏良子按个摩。足疗+肩颈全套一百五，技师手法专业，会重点按斜方肌。包间有电视，可以躺着看剧。',19,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(10,30,110,'星巴克万象天地 早C晚A','','万象天地L1的星巴克，早上去杯美式写代码，下午换杯星冰乐和朋友聊天。座位多，插座够用，Wi-Fi稳定。',21,3,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(11,4,111,'农畉LONFOOD 轻食减脂期友好','','万象天地的农畉，三文鱼温泉蛋碗很适合减脂期，牛油果、藜麦、温泉蛋搭配。环境ins风，适合拍照打卡。人均八十。',18,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(12,9,112,'八合里海记 现切牛肉火锅','','福田COCO Park的八合里，现切牛肉当天屠宰，吊龙、匙柄、嫩肉必点。牛肉涮八秒就熟，沙茶酱蘸料是灵魂。人均九十，新鲜看得见。',24,4,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(13,1,113,'王繁星面馆 上海拌川正宗','','COCO Park B1的王繁星，上海本帮拌川，猪肝腰花双拼是招牌。浓油赤酱，面条劲道。出餐快，人均四十五，打工人午餐首选。',15,1,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(14,6,114,'四季椰林 椰子鸡清淡养生','','龙岗COCO Park的四季椰林，三个现开椰子做锅底，清甜不腻。文昌鸡皮滑肉嫩，蘸沙姜酱油。最后煮碗腊味煲仔饭，绝了。',20,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(15,19,115,'奈瑞儿 面部护理放松一下','','深圳湾万象城的奈瑞儿，做了个补水面部护理。环境私密单间，美容师手法轻柔，全程无推销。做完脸嫩了一个度。',17,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(16,16,116,'魅KTV 深夜场划算','','魅KTV晚上十点后三小时九十块，屏幕大曲库全。自助点歌系统流畅，音效不错。适合夜猫子聚会。',16,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(17,13,117,'太二酸菜鱼 酸菜比鱼好吃','','万象天地的太二，老坛子酸菜鱼，口号就是\"酸菜比鱼好吃\"。黑鱼无刺滑嫩，酸菜脆爽开胃，酸汤泡米饭能连干三碗。米饭五常米免费续。',23,3,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(18,29,118,'威廉古堡轰趴馆 团建包场','','部门团建包了威廉古堡，KTV、桌游、Switch、麻将全都有。三十人包场一下午，人均五十。场地布置可以自己提前弄。',14,1,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(19,2,119,'蜀大侠火锅 成都网红火锅','','福田中心城的蜀大侠，牛油锅底麻辣醇厚。贵妃牛肉泡牛奶浴后下锅，嫩到离谱。冰川鹅肠脆爽，毛肚七上八下。人均一百一。',27,4,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(20,21,120,'乐刻运动 24小时健身房','','壹方城的乐刻，24小时营业，月付制不用办年卡。器械齐全，人不多，随时能练。月卡一百多，比传统健身房灵活。',13,1,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(21,7,121,'半天妖烤鱼 青花椒麻得过瘾','','万象城B1的半天妖，青花椒烤鱼麻味突出，鱼肉嫩到夹不起来。配菜随便加，米饭无限续。人均八十，性价比高。',19,2,'2026-10-19 14:43:10','2026-10-19 15:10:27'),(22,28,122,'JZ Club 爵士之夜','','万象天地里巷的JZ Club，每周有爵士现场演出。氛围很好，适合喜欢音乐的人。门票一百左右，含一杯饮品。',22,3,'2026-10-19 14:43:10','2026-10-19 15:10:27');
