-- 笔记配图：没有配图的笔记沿用所属店铺的照片，避免社区一片空白
UPDATE `tb_blog` b JOIN `tb_shop` s ON s.id = b.shop_id SET b.images = s.images WHERE b.images = '';
-- 让笔记正文带上店名，便于按店铺关联展示（原始示例笔记只有正文、没有店名）
UPDATE `tb_blog` b JOIN `tb_shop` s ON s.id = b.shop_id
SET b.content = CONCAT(SUBSTRING_INDEX(SUBSTRING_INDEX(s.name,'（',1),'(',1), ' 探店：', b.content);
-- 列表页展示的评论数按真实评论重算，避免「显示有评论、点进去是空」
UPDATE `tb_blog` SET `comments` = (SELECT COUNT(*) FROM `tb_blog_comments` c WHERE c.`blog_id` = `tb_blog`.`id`);

